query:
SELECT 'sponsors' as tbl, id, companyName, contactName, contactEmail FROM sponsors WHERE companyName LIKE '%Perch%' OR companyName LIKE '%Peak%';
SELECT 'rankingsSubmissions' as tbl, id, sponsorId, submittedAt, status, isArchived FROM rankingsSubmissions WHERE sponsorId IN (SELECT id FROM sponsors WHERE companyName LIKE '%Perch%' OR companyName LIKE '%Peak%');
SELECT 'intakeSubmissions' as tbl, id, sponsorId, companyName, firstName, lastName, email FROM intakeSubmissions WHERE companyName LIKE '%Perch%';

